package io.github.strogolsky.profinder.common.entity;

import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import lombok.Getter;
import lombok.Setter;

import java.util.UUID;

/**
 * Base class of the entities that have a generated UUID identifier (and the version of {@link VersionedEntity}).
 */
@Getter
@Setter
@MappedSuperclass
public abstract class BaseEntity extends VersionedEntity {

    /**
     * Unique identifier, generated by the application (UUID v4) when the entity is first saved.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;
}
